import { chromium } from 'playwright';
import fs from 'fs';

const shotDir = '/tmp/shots';
fs.mkdirSync(shotDir, { recursive: true });

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => errors.push(String(err)));

async function shot(name) {
  await page.screenshot({ path: `${shotDir}/${name}.png` });
  console.log('screenshot:', name);
}

// 1. Product list
await page.goto('http://localhost:4200/products');
await page.waitForSelector('.product-card', { timeout: 15000 });
await shot('01-product-list');

// 2. Filter by subcategory
await page.click('text=Kopfhörer');
await page.waitForTimeout(500);
await shot('02-filtered-subcategory');
const cardCountAfterFilter = await page.locator('.product-card').count();
console.log('cards after subcategory filter:', cardCountAfterFilter);

// 3. Sort by price desc
await page.selectOption('select', 'price_desc');
await page.waitForTimeout(500);
await shot('03-sorted-price-desc');

// 4. Search
await page.click('text=Alle Kategorien');
await page.waitForTimeout(300);
await page.fill('input[type="search"]', 'Mixer');
await page.press('input[type="search"]', 'Enter');
await page.waitForTimeout(500);
await shot('04-search-mixer');
console.log('search result text:', await page.locator('.product-grid').textContent());

// 5. Go to product detail
await page.click('text=Alle Kategorien');
await page.waitForTimeout(300);
await page.fill('input[type="search"]', '');
await page.press('input[type="search"]', 'Enter');
await page.waitForTimeout(300);
await page.click('.product-card >> nth=0');
await page.waitForSelector('.product-detail', { timeout: 10000 });
await shot('05-product-detail');

// 6. Add to cart
await page.click('button:has-text("In den Warenkorb")');
await page.waitForSelector('.confirmation');
await shot('06-added-to-cart');

// 7. Rate the product
await page.fill('.rating-form input[type="text"]', 'Testkäufer');
await page.selectOption('.rating-form select', '5');
await page.click('button:has-text("Bewertung abschicken")');
await page.waitForTimeout(800);
await shot('07-rated');

// 8. Go to cart
await page.click('text=Warenkorb');
await page.waitForSelector('.cart-table', { timeout: 10000 });
await shot('08-cart');

// 9. Checkout
await page.click('text=Zur Kasse');
await page.waitForSelector('form', { timeout: 10000 });
await page.fill('input[name="name"]', 'Max Mustermann');
await page.fill('input[name="strasse"]', 'Musterstr. 1');
await page.fill('input[name="plz"]', '12345');
await page.fill('input[name="ort"]', 'Berlin');
await page.fill('input[name="land"]', 'Deutschland');
await page.fill('input[name="email"]', 'max@example.com');
await page.fill('input[name="telefon"]', '0123456789');
await shot('09-checkout-form');
await page.click('button:has-text("Bestellung abschicken")');
await page.waitForURL(/\/orders\/\d+/, { timeout: 10000 });
await shot('10-order-confirmation');
console.log('order url:', page.url());
console.log('order page text:', await page.locator('body').textContent());

console.log('CONSOLE ERRORS:', JSON.stringify(errors));

await browser.close();

